'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',plus:'<path d="M12 5v14M5 12h14"/>',ticket:'<path d="M4 4h16v5a3 3 0 0 0 0 6v5H4v-5a3 3 0 0 0 0-6z"/><path d="M9 4v3m0 4v2m0 4v3"/>',sparkles:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5zM20 2v4m-2-2h4"/>',book:'<path d="M12 5v16M3 3c4 0 6 1 9 3 3-2 5-3 9-3v15c-4 0-6 1-9 3-3-2-5-3-9-3z"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',chart:'<path d="M4 3v17h17M8 16v-5m5 5V7m5 9V4"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>',bell:'<path d="M6 9a6 6 0 0 1 12 0c0 7 3 7 3 9H3c0-2 3-2 3-9m4 12h4"/>',settings:'<path d="M12 3v3m0 12v3M3 12h3m12 0h3M5.6 5.6l2.1 2.1m8.6 8.6 2.1 2.1m0-12.8-2.1 2.1m-8.6 8.6-2.1 2.1"/><circle cx="12" cy="12" r="6"/><circle cx="12" cy="12" r="2"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="m12 3 8 3v6c0 4-8 9-8 9s-8-5-8-9V6z"/><path d="m8 12 3 3 5-6"/>',monitor:'<rect x="3" y="3" width="18" height="13" rx="2"/><path d="M12 16v5m-5 0h10"/>',wifi:'<path d="M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0m-11 4a6 6 0 0 1 8 0"/><circle cx="12" cy="20" r=".7"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-8z"/>',chair:'<path d="M6 12V3h12v9M4 11v6h16v-6M6 17v5m12-5v5M4 14h16"/>',drop:'<path d="M12 2S5 10 5 15a7 7 0 0 0 14 0c0-5-7-13-7-13Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="1.5"/><path d="m3 17 6-6 5 5 3-3 4 4"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 4v3"/>',logout:'<path d="M10 3H4v18h6m4-14 5 5-5 5m-5-5h10"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',qr:'<path d="M3 3h6v6H3zm12 0h6v6h-6zM3 15h6v6H3zm12 0h3v3h-3zm3 3h3v3h-3zM12 3v6m0 3h9M3 12h6m3 3v6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',refresh:'<path d="M20 8a8 8 0 0 0-14-3L3 8m0-5v5h5M4 16a8 8 0 0 0 14 3l3-3m0 5v-5h-5"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m2-17a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5v2"/>',send:'<path d="m22 2-7 20-4-9-9-4zM11 13 22 2"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9z"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-11v2"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',printer:'<path d="M6 9V3h12v6M6 17H3V9h18v8h-3M6 14h12v7H6z"/>'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.grid}</svg>`;
const box=name=>`<span class="icon-box">${icon(name)}</span>`;
const btn=(label,action,style='primary',extra='')=>`<button class="btn ${style}" data-action="${action}" ${extra}>${label}</button>`;
const statusBadge=s=>`<span class="badge ${esc(s)}">${esc(state.meta.statuses[s]||s)}</span>`;
const priorityBadge=s=>`<span class="priority ${esc(s)}">${esc(state.meta.priorities[s]||s)}</span>`;
const date=v=>v?new Intl.DateTimeFormat('ru-RU',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(v)):'—';
const field=(label,input,hint='')=>`<label class="field"><span>${label}</span>${input}${hint?`<small>${hint}</small>`:''}</label>`;
const input=(name,placeholder='',value='',extra='')=>`<input name="${name}" placeholder="${esc(placeholder)}" value="${esc(value)}" ${extra}>`;
const select=(name,options,value='',placeholder='Выберите',extra='')=>`<select name="${name}" ${extra}>${placeholder!==null?`<option value="">${placeholder}</option>`:''}${options.map(o=>`<option value="${esc(o.id)}" ${String(o.id)===String(value)?'selected':''}>${esc(o.name)}</option>`).join('')}</select>`;
const title=(heading,description='',actions='')=>`<div class="page-title"><div><h1>${heading}</h1><p>${description}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;
const empty=(heading,description,action='')=>`<div class="empty">${box('ticket')}<h3>${heading}</h3><p>${description}</p>${action}</div>`;
const errorSlot='<div class="form-error" role="alert"></div>';
const state={meta:null,user:null,draft:{},photo:null,chat:[],ticket:null,staff:[],requestKey:null,lastCreated:null,routeVersion:0};
const routeInfo=()=>{const [p,q='']=(location.hash.slice(1)||'/').split('?');return{path:p,params:new URLSearchParams(q)}};
const go=p=>{if(location.hash==='#'+p)render();else location.hash=p};
const randomKey=()=>Array.from(crypto.getRandomValues(new Uint8Array(32)),x=>x.toString(16).padStart(2,'0')).join('');
function saved(){try{return JSON.parse(localStorage.getItem('upk-own-tickets')||'[]')}catch{return[]}}
function saveOwn(item){try{const items=saved().filter(x=>x.token!==item.token);localStorage.setItem('upk-own-tickets',JSON.stringify([item,...items].slice(0,50)))}catch{toast('Сохраните ссылку вручную: браузер не разрешил локальное хранение.')}}
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500)}
async function api(path,options={}){
 const headers={'X-UPK-Request':'1',...options.headers};if(options.body&&typeof options.body!=='string'){headers['Content-Type']='application/json';options.body=JSON.stringify(options.body)}
 let response;try{response=await fetch('/api'+path,{...options,headers})}catch{throw Error('Нет связи с сервером. Проверьте подключение и повторите попытку.')}
 let result;try{result=await response.json()}catch{throw Error('Сервер вернул неожиданный ответ.')}
 if(!response.ok){const err=Error(result.error||'Не удалось выполнить действие.');err.status=response.status;throw err}return result;
}
async function reloadMeta(){state.meta=await api('/meta');state.user=state.meta.user}
function shell(content){
 const {path}=routeInfo();const active=p=>path===p||(p!=='/'&&path.startsWith(p+'/'))?'active':'';
 const link=(p,name,i)=>`<a class="nav-item ${active(p)}" href="#${p}" ${active(p)?'aria-current="page"':''}>${icon(i)}${name}</a>`;
 const staff=state.user;const current=({'/':'Главная','/new':'Новое обращение','/mine':'Мои обращения','/assistant':'Помощник','/knowledge':'База знаний','/dashboard':'Обзор','/tickets':'Все заявки','/analytics':'Аналитика','/locations':'Помещения и QR','/settings':'Настройки','/notifications':'Уведомления','/login':'Вход сотрудника'})[path]||(path.startsWith('/track')?'Отслеживание':'Карточка заявки');
 $('#app').innerHTML=`<button class="mobile-scrim" data-action="menu" aria-label="Закрыть меню"></button><aside class="sidebar" aria-label="Основное меню"><a class="brand" href="#/"><img src="/static/assets/college-logo.jpeg" alt="Логотип ДГУ"><div><strong>УПК<span class="sr-only"> — цифровой помощник</span></strong><span>ЦИФРОВОЙ ПОМОЩНИК<br>КОЛЛЕДЖА ДГУ</span></div></a><nav><div class="nav-label">Ваш колледж</div>${link('/','Главная','home')}${link('/new','Новое обращение','plus')}${link('/mine','Мои обращения','ticket')}${link('/assistant','Помощник','sparkles')}${link('/knowledge','База знаний','book')}${staff?`<div class="nav-label">Рабочее пространство</div>${link('/dashboard','Обзор','grid')}${link('/tickets','Все заявки','ticket')}${link('/analytics','Аналитика','chart')}`:''}${link('/locations','Помещения и QR','qr')}${staff?`${link('/notifications','Уведомления','bell')}${staff.role==='admin'?link('/settings','Настройки','settings'):''}`:`<div class="nav-label">Сотрудникам</div>${link('/login','Войти в панель УПК','lock')}`}</nav><div class="side-bottom"><div class="side-tip">${icon('shield')}<br><strong>Колледж, в котором комфортно</strong><p>Ваши обращения помогают нам становиться лучше каждый день.</p></div><p class="version">УПК · Хакатон 2026 · v1.0</p></div></aside><div class="workspace"><header class="topbar"><button class="menu-toggle" data-action="menu" aria-label="Открыть меню">${icon('menu')}</button><div class="breadcrumb">Цифровой помощник ${icon('chevron')}<strong>${esc(current)}</strong></div><div class="topbar-right"><span class="live-label"><span class="live-dot"></span>Сервис обращений колледжа</span>${staff?`<div class="profile"><span class="avatar">${esc(staff.name.split(' ').slice(0,2).map(x=>x[0]).join(''))}</span><div class="profile-text">${esc(staff.name)}<small>${staff.role==='admin'?'Администратор':'Сотрудник УПК'}</small></div></div><button class="close" data-action="logout" title="Выйти" aria-label="Выйти">${icon('logout')}</button>`:`<a class="btn sm" href="#/login">${icon('lock')}Вход сотрудника</a>`}</div></header><main class="main" id="main" tabindex="-1">${content}<footer class="footer"><span>© 2026 · Цифровой помощник колледжа ДГУ</span><span>${icon('shield')}Заботимся о вашем учебном пространстве</span></footer></main></div>`;
}
function home(){return `${title('Рады видеть вас 👋','Всё, что нужно для комфортной учёбы — в одном месте.')}<section class="hero"><div><div class="hero-tag">${icon('sparkles')}Небольшое обращение — большие изменения</div><h1>Забота о колледже<br>начинается <span>с вас.</span></h1><p>Сообщите о неисправности, найдите полезную инструкцию или проверьте статус обращения. Мы поможем разобраться.</p><div class="actions"><a class="btn primary" href="#/new">${icon('plus')}Сообщить о проблеме</a><a class="btn ghost" href="#/assistant">Спросить помощника ${icon('arrow')}</a></div></div><div class="hero-visual" aria-hidden="true"><div class="demo-stamp">${icon('check')}Понятный путь к решению</div><div class="help-card"><div class="help-card-head">${box('ticket')}<div><strong>Ваше обращение</strong><small>Каждая деталь имеет значение</small></div></div><div class="line"></div><div class="line short"></div><div class="process-row"><span class="process-dot">1</span><span class="process-line"></span><span class="process-dot light">2</span><span class="process-line"></span><span class="process-dot light">${icon('check')}</span></div><div class="process-row" style="justify-content:space-between;margin-top:10px;font-size:9px"><span>Отправка</span><span>В работе</span><span>Решение</span></div></div><div class="float-symbol">${icon('shield')}</div></div></section><div class="grid-3"><a href="#/new" class="card action-card">${box('plus')}${icon('arrow')}<h3>Создать обращение</h3><p>Расскажите, что случилось.<br>Мы направим заявку сотруднику.</p></a><a href="#/mine" class="card action-card">${box('ticket')}${icon('arrow')}<h3>Проверить статус</h3><p>Узнайте, как продвигается<br>решение вашей проблемы.</p></a><a href="#/assistant" class="card action-card">${box('sparkles')}${icon('arrow')}<h3>Спросить помощника</h3><p>Получите подсказку<br>по инструкциям колледжа.</p></a></div><div class="home-bottom"><section><div class="section-head"><h2>Полезно знать</h2><a class="btn ghost" href="#/knowledge">Все инструкции ${icon('arrow')}</a></div><div class="card">${state.meta.knowledge.slice(0,3).map(a=>`<a href="#/knowledge/${a.id}" class="article-row">${box(a.id==='printer'?'printer':a.id==='computer'?'shield':'monitor')}<div><h3>${esc(a.title)}</h3><p>${esc(a.summary)}</p></div>${icon('chevron')}</a>`).join('')}</div></section><section><div class="section-head"><h2>Как это работает</h2><span class="muted small">3 простых шага</span></div><div class="card">${[['Расскажите о проблеме','Выберите помещение и опишите ситуацию.'],['Мы передадим её сотруднику','Обращение попадёт в единый журнал УПК.'],['Следите за решением','Сохраните ссылку и проверяйте статус.']].map((s,i)=>`<div class="step"><span class="step-number">${i+1}</span><div><h3>${s[0]}</h3><p>${s[1]}</p></div></div>`).join('')}</div></section></div>`}
function newTicket(){
 const d=state.draft;const locKey=routeInfo().params.get('location');const loc=state.meta.locations.find(x=>x.qr_key===locKey);const invalid=locKey&&!loc;
 if(loc)d.location_id=loc.id;if(!state.requestKey)state.requestKey=randomKey();
 const locations=state.meta.locations.map(x=>({id:x.id,name:`${x.building} · ${x.room} · ${x.zone_name}`}));
 return `${title('Новое обращение','Расскажите о проблеме — поможем найти решение.')}<div class="form-layout"><form id="new-ticket-form" class="card">${errorSlot}${loc?`<div class="hint success">${icon('pin')}Помещение определено по QR-коду: <strong>${esc(loc.room)}</strong>. При необходимости его можно изменить.</div>`:''}${invalid?'<div class="hint warning">QR-код не связан с известным помещением. Выберите место вручную.</div>':''}<div class="form-section"><div class="form-section-title"><span class="mini-number">01</span>Что случилось?</div>${field('Описание проблемы',`<textarea name="description" required minlength="10" maxlength="4000" placeholder="Например: в кабинете 214 не работает проектор. При включении нет изображения…">${esc(d.description||'')}</textarea>`,'Укажите, что не работает и когда вы заметили проблему. От 10 символов.')}<div class="actions">${btn(icon('sparkles')+'Подсказать категорию','analyze-draft','soft','type="button"')}<span class="demo-badge">Демонстрационный помощник</span></div><div id="draft-analysis"></div><div class="spacer"></div>${field('Краткая тема',input('title','Например: не работает проектор',d.title||'','required minlength="5" maxlength="150"'))}${field('Категория',select('category_id',state.meta.categories,d.category_id||'','Выберите категорию','required'))}</div><div class="form-section"><div class="form-section-title"><span class="mini-number">02</span>Где нужна помощь?</div>${field('Корпус и помещение',select('location_id',locations,d.location_id||'','Выберите помещение','required'),'Можно выбрать вручную или перейти по QR-коду у входа.')}<div id="similar-result"></div></div><div class="form-section"><div class="form-section-title"><span class="mini-number">03</span>Дополнительные детали <span class="optional muted small">необязательно</span></div><div class="field"><span>Фотография</span><label class="upload">${icon('upload')}<span><strong>Добавьте фото проблемы</strong><small>JPEG, PNG или WebP · до 5 МБ</small><input type="file" id="photo-input" accept="image/jpeg,image/png,image/webp" aria-label="Выберите фотографию"></span></label><div id="photo-preview"></div><small>Фотографируйте только если это безопасно. Не включайте в кадр личные данные.</small></div>${field('Как к вам обращаться <span class="optional">необязательно</span>',input('requester_name','Ваше имя',d.requester_name||'','maxlength="100"'))}<details><summary class="blue small">Получать уведомления по email или Telegram</summary><div class="hint">${state.meta.notification_mode==='demo'?'Деморежим: уведомления появятся в журнале сотрудника, но не будут отправлены. Реальную отправку можно подключить в настройках сервера.':'Уведомления будут поставлены в очередь отправки. Для Telegram сначала начните диалог с настроенным ботом.'}</div><div class="field-row">${field('Email',input('email','you@example.com','','type="email" maxlength="200"'))}${field('Telegram chat ID',input('telegram_chat_id','Числовой ID диалога','','maxlength="40"'),'Именно chat ID, а не @username.')}</div><label class="check"><input type="checkbox" name="notification_consent">Согласен использовать указанные контакты для уведомлений по этой заявке.</label></details></div><div class="hint">${icon('lock')}После отправки вы получите секретную ссылку для отслеживания. Регистрация не нужна.</div><button class="btn primary w-full" type="submit">Отправить обращение ${icon('arrow')}</button><p class="muted small text-center" style="font-size:10px;margin:12px 0 0">Нажимая «Отправить», вы подтверждаете описание и место проблемы.</p></form><aside class="side-panel stack"><div class="card assistant-card">${box('sparkles')}<h3>Помощник рядом</h3><p>Не знаете, с чего начать? Опишите ситуацию, и помощник предложит категорию и безопасную инструкцию.</p><span class="demo-badge">Работает по базе знаний</span></div><div class="card"><h3>Хорошая заявка — это</h3>${[['Точное место','Корпус, кабинет или общая зона.'],['Понятное описание','Что случилось и что вы заметили.'],['Фото, если безопасно','Поможет сотруднику оценить ситуацию.']].map((x,i)=>`<div class="step" style="margin-top:20px"><span class="step-number">${i+1}</span><div><h3>${x[0]}</h3><p>${x[1]}</p></div></div>`).join('')}</div><div class="hint warning">${icon('shield')}При дыме, искрении или запахе гари отойдите и немедленно сообщите ответственному сотруднику. Не ждите ответа на заявку.</div></aside></div>`;
}
function createdPage(){const t=state.lastCreated;if(!t)return empty('Ссылка не сохранена в этой вкладке','Откройте раздел «Мои обращения», чтобы найти свою заявку.','<a class="btn primary" href="#/mine">Мои обращения</a>');const link=location.origin+location.pathname+'#/track/'+t.token;return `<div class="card success-card"><div class="success-check">${icon('check')}</div><div class="eyebrow">${esc(t.public_number)}</div><h1>Обращение зарегистрировано</h1><p class="muted">Спасибо, что помогаете заботиться о колледже.<br>Заявка поступила сотрудникам УПК.</p>${statusBadge('new')}<div class="token-box"><span class="muted small">Ваша секретная ссылка</span><p style="margin:8px 0 0">${esc(link)}</p></div><div class="actions" style="justify-content:center">${btn(icon('copy')+'Скопировать ссылку','copy-tracking','soft',`data-token="${t.token}"`)}<a class="btn primary" href="#/track/${t.token}">Отследить заявку ${icon('arrow')}</a></div><div class="hint">Сохраните ссылку. Она предоставляет доступ к заявке и комментариям — не публикуйте её.</div><a class="btn ghost" href="#/new">Создать ещё одно обращение</a></div>`}
function minePage(){const own=saved();return `${title('Мои обращения','Отслеживайте решение по секретной ссылке или коду доступа.','<a href="#/new" class="btn primary">'+icon('plus')+'Новое обращение</a>')}<div class="card"><form id="track-form">${errorSlot}<div class="field-row" style="grid-template-columns:1fr auto;align-items:end">${field('Ссылка или код доступа',input('token','Вставьте секретную ссылку из подтверждения','','required'))}<button class="btn primary" style="margin-bottom:19px">Открыть ${icon('arrow')}</button></div></form><p class="muted small" style="margin-bottom:0">По одному номеру открыть заявку нельзя — это защищает ваши данные.</p></div><div class="section-head"><h2>Сохранено на этом устройстве</h2><span class="muted small">${own.length} обращений</span></div><div class="card">${own.length?own.map(x=>`<div class="my-ticket">${box('ticket')}<a class="my-ticket-content" href="#/track/${esc(x.token)}"><strong>${esc(x.title)}</strong><small>${esc(x.public_number)} · ${date(x.created_at)}</small></a><a class="btn sm" href="#/track/${esc(x.token)}">Открыть ${icon('arrow')}</a><button class="close" data-action="forget" data-token="${esc(x.token)}" title="Убрать с этого устройства" aria-label="Убрать сохранённую ссылку">${icon('close')}</button></div>`).join(''):empty('Пока нет сохранённых обращений','После отправки здесь появится ссылка на вашу заявку. На другом устройстве используйте сохранённый код.')}</div>`}
function loginPage(){return `<div class="login-wrap"><div class="card">${box('lock')}<h1>Вход в панель УПК</h1><p>Рабочее пространство для сотрудников и администрации колледжа.</p><form id="login-form">${errorSlot}${field('Логин',input('login','Введите логин','','required autocomplete="username"'))}${field('Пароль',input('password','Введите пароль','','type="password" required autocomplete="current-password"'))}<button class="btn primary w-full" type="submit">Войти ${icon('arrow')}</button></form><div class="hint">Для проверки проекта используйте аккаунты <strong>admin</strong>, <strong>staff</strong> или <strong>technician</strong>. Уникальные пароли показаны в терминале первого запуска и сохранены в <code>.data/demo-accounts.txt</code>.</div><a class="btn ghost" href="#/">${icon('home')}На главную</a></div><p class="small muted text-center" style="margin-top:20px">Для отправки и отслеживания заявки вход не требуется.</p></div>`}
function articleContent(a){return `<div class="article-content"><p class="muted">${esc(a.summary)}</p><ol>${a.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="hint warning">${icon('shield')}${esc(a.warning)}</div><p class="source">Источник: ${esc(a.source)}</p></div>`}
function knowledgePage(id){const a=state.meta.knowledge.find(x=>x.id===id);if(id&&!a)return empty('Инструкция не найдена','Откройте полный список.','<a class="btn primary" href="#/knowledge">База знаний</a>');if(a)return `${title(esc(a.title),'Проверенная инструкция — безопасные действия.','<a class="btn" href="#/knowledge">Все инструкции</a>')}<div class="form-layout"><article class="card">${articleContent(a)}</article><aside class="card assistant-card">${box('ticket')}<h3 style="margin-top:20px">Инструкция не помогла?</h3><p class="muted small">Если оборудование неисправно, оформите обращение. Сотрудник проверит проблему.</p><a class="btn primary" href="#/new">Создать обращение</a></aside></div>`;return `${title('База знаний','Инструкции колледжа и ответы на частые вопросы.')}<div class="card" style="margin-bottom:24px"><label class="sr-only" for="kb-search">Поиск по инструкциям</label><input id="kb-search" placeholder="Найти инструкцию, например: проектор" type="search"></div><div id="knowledge-results" class="grid-3">${knowledgeCards(state.meta.knowledge)}</div>`}
function knowledgeCards(articles){return articles.length?articles.map(a=>`<article class="card knowledge-card">${box(a.category==='equipment'?'monitor':a.id==='tracking'?'ticket':'book')}<h3>${esc(a.title)}</h3><p>${esc(a.summary)}</p><a href="#/knowledge/${a.id}" class="btn ghost">Читать инструкцию ${icon('arrow')}</a></article>`).join(''):empty('Инструкций не найдено','Попробуйте другое слово или задайте вопрос помощнику.','<a class="btn" href="#/assistant">Спросить помощника</a>')}
function assistantResult(r,create=true){const labels={question:'Информационный вопрос',fault:'Нужна помощь сотрудника',danger:'Возможная опасность',unknown:'Недостаточно проверенных данных',clarify:'Нужно уточнение'};const a=state.meta.knowledge.find(x=>x.id===r.knowledge_id);return `<div class="hint ${r.kind==='danger'?'danger':r.kind==='question'?'success':''}"><strong>${esc(labels[r.kind])}</strong><p style="margin:7px 0 0">${esc(r.message)}</p>${r.kind!=='question'?`<div style="margin-top:10px">Категория: ${esc(state.meta.categories.find(x=>x.id===r.category)?.name||'Другое')} · Приоритет: ${esc(state.meta.priorities[r.priority])}</div>`:''}</div>${a?`<details ${r.kind==='question'?'open':''}><summary class="blue">${esc(a.title)}</summary>${articleContent(a)}</details>`:''}${create?`<div class="actions" style="margin-top:14px">${btn(icon('plus')+(r.kind==='question'?'Не помогло — создать заявку':'Создать заявку'),'chat-to-ticket','soft')}<span class="muted" style="font-size:9px">Демо · ${r.confidence==='high'?'ответ по правилам и базе знаний':'решение передаётся человеку'}</span></div>`:''}`}
function chatPage(){return `${title('Помощник колледжа','Поможет с инструкцией или подготовит обращение.')}<div class="assistant-layout"><section class="card chat-shell"><div class="chat-header">${box('sparkles')}<div><strong>Цифровой помощник УПК</strong><small>Инструкции колледжа всегда под рукой</small></div><span class="demo-badge" style="margin-left:auto">Деморежим</span></div><div class="chat-messages" id="chat-messages"><div class="chat-message">${box('sparkles')}<div class="chat-bubble"><p>Здравствуйте! Я помогу разобраться с вопросом или оформить заявку сотруднику.</p><p>Например, спросите, как подключить проектор, или расскажите, что случилось.</p></div></div>${state.chat.map((m,index)=>m.role==='user'?`<div class="chat-message user"><div class="chat-bubble">${esc(m.text)}</div></div>`:`<div class="chat-message">${box('sparkles')}<div class="chat-bubble" data-chat-index="${index}">${assistantResult(m.result)}</div></div>`).join('')}</div><form class="chat-form" id="chat-form">${errorSlot}<div class="chat-input"><label class="sr-only" for="chat-input">Ваш вопрос</label><input id="chat-input" name="text" required minlength="2" maxlength="4000" placeholder="Опишите проблему или задайте вопрос…"><button class="btn primary" aria-label="Отправить сообщение">${icon('send')}</button></div><p class="muted" style="font-size:9px;margin:10px 0 0">Демонстрационная классификация по правилам. Ответы из базы знаний, без внешней языковой модели.</p></form></section><aside class="stack"><div class="card"><h3>Можно спросить так</h3><div class="suggestions-list">${['Как подключить ноутбук к проектору?','В кабинете 214 не работает проектор','Где посмотреть статус заявки?'].map(t=>`<button class="suggestion" data-action="ask-example" data-text="${esc(t)}">${esc(t)} ${icon('arrow')}</button>`).join('')}</div></div><div class="card aside-description">${box('shield')}<h3 style="margin-top:18px">Безопасность важнее</h3><p class="muted small">Помощник не предлагает ремонт электроприборов, не знает паролей и не обещает сроки.</p><p class="muted small" style="margin:0">Ответ помощника не регистрирует и не закрывает заявку. Отправку всегда подтверждаете вы.</p></div></aside></div>`}
function statCards(s){return `<div class="stats-grid">${[['Всего обращений',s.total,'ticket','За всё время'],['Открытые заявки',s.open,'clock',`${s.new} ожидают рассмотрения`],['Решённые заявки',s.resolved,'check','Результат зафиксирован сотрудником'],['Среднее время решения',s.average_hours===null?'—':s.average_hours+' ч','chart','От создания до решения']].map(([l,v,i,c])=>`<div class="card stat"><div class="label">${l}</div>${box(i)}<div class="value">${v}</div><div class="caption">${c}</div></div>`).join('')}</div>`}
function ticketTable(items){return items.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Обращение</th><th>Категория</th><th>Помещение</th><th>Статус</th><th>Приоритет</th><th>Дата создания</th><th><span class="sr-only">Открыть</span></th></tr></thead><tbody>${items.map(t=>`<tr><td><div class="ticket-number">${esc(t.public_number)}</div><a class="ticket-subject" href="#/ticket/${t.id}" title="${esc(t.title)}">${esc(t.title)}</a></td><td>${esc(t.category_name)}</td><td>${esc(t.room)}</td><td>${statusBadge(t.status)}</td><td>${priorityBadge(t.priority)}</td><td>${date(t.created_at).replace(' г.','')}</td><td><a href="#/ticket/${t.id}" aria-label="Открыть ${esc(t.public_number)}">${icon('chevron')}</a></td></tr>`).join('')}</tbody></table></div>`:empty('Заявок не найдено','Попробуйте изменить фильтры или поисковый запрос.',btn('Сбросить фильтры','reset-filters','soft'))}
function categoryBars(categories){const max=Math.max(1,...categories.map(c=>c.count));return categories.map(c=>`<div class="bar-row"><div class="bar-label"><span>${esc(c.name)}</span><strong>${c.count}</strong></div><div class="bar-track"><div class="bar-fill" style="width:${c.count/max*100}%"></div></div></div>`).join('')}
function daysChart(days){const values=new Map(days.map(x=>[x.day,x.count]));const dates=Array.from({length:14},(_,i)=>{const d=new Date();d.setUTCDate(d.getUTCDate()-13+i);return d.toISOString().slice(0,10)});const max=Math.max(1,...values.values());return `<div class="chart" role="img" aria-label="Обращения за 14 дней: ${esc(dates.map(d=>d+': '+(values.get(d)||0)).join(', '))}">${dates.map(d=>`<div class="chart-column"><div class="chart-bar" style="height:${(values.get(d)||0)/max*100}%" title="${d}: ${values.get(d)||0}"><span>${values.get(d)||''}</span></div><small>${d.slice(8)}.${d.slice(5,7)}</small></div>`).join('')}</div>`}
async function dashboardPage(){const [s,t]=await Promise.all([api('/stats'),api('/tickets')]);return `${title('Обзор обращений','Помогаем колледжу работать без сбоев.','<a href="#/tickets" class="btn primary">'+icon('ticket')+'Все заявки</a>')}${statCards(s.totals)}${s.totals.urgent?`<div class="hint danger">${icon('bolt')}Срочных открытых обращений: ${s.totals.urgent}. Проверьте их в первую очередь.</div>`:''}<div class="grid-2"><section class="card"><div class="card-head"><h2>Динамика обращений</h2><span class="muted small">14 дней</span></div>${daysChart(s.days)}</section><section class="card"><div class="card-head"><h2>По категориям</h2><a class="btn ghost" href="#/analytics">Подробнее ${icon('arrow')}</a></div>${categoryBars(s.categories.filter(c=>c.count).slice(0,4))||'<p class="muted">Пока нет данных.</p>'}</section></div><div class="section-head"><h2>Заявки в фокусе</h2><a class="btn ghost" href="#/tickets">Все обращения ${icon('arrow')}</a></div><div class="card table-card">${ticketTable(t.items.slice(0,6))}</div><div class="hint" style="font-size:10px">Начальная база содержит демонстрационные обращения. Новые заявки, изменения и показатели сохраняются в SQLite.</div>`}
async function ticketsPage(){const p=routeInfo().params;const t=await api('/tickets?'+p.toString());return `${title('Все заявки','Единый журнал обращений колледжа.',`<a class="btn" href="/api/export.csv?${esc(p.toString())}">${icon('download')}Экспорт CSV</a>`)}<section class="card table-card"><div class="tabs">${[['','Все обращения'],['new','Новые'],['in_progress','В работе'],['needs_info','Нужны уточнения'],['resolved','Решённые']].map(([s,l])=>`<button class="tab ${(p.get('status')||'')===s?'active':''}" data-action="ticket-tab" data-status="${s}">${l}</button>`).join('')}</div><form id="filters-form" class="filters"><div class="search"><label class="sr-only" for="ticket-search">Поиск по номеру и описанию</label><input id="ticket-search" name="q" placeholder="Поиск по номеру или описанию…" value="${esc(p.get('q')||'')}"></div>${select('status',Object.entries(state.meta.statuses).map(([id,name])=>({id,name})),p.get('status'),'Все статусы','aria-label="Статус"')}${select('category_id',state.meta.categories,p.get('category_id'),'Все категории','aria-label="Категория"')}${select('location_id',state.meta.locations.map(l=>({id:l.id,name:l.room+' · '+l.zone_name})),p.get('location_id'),'Все помещения','aria-label="Помещение"')}<input type="date" name="date_from" value="${esc(p.get('date_from')||'')}" aria-label="Дата от"><input type="date" name="date_to" value="${esc(p.get('date_to')||'')}" aria-label="Дата до"><button class="btn soft" type="submit">${icon('search')}Найти</button><button class="btn sm" type="button" data-action="reset-filters">Сбросить</button></form>${ticketTable(t.items)}<div class="pagination"><span>Найдено: ${t.total} · Страница ${t.page} из ${t.pages}</span><div class="actions"><button class="btn sm" data-action="page" data-page="${t.page-1}" ${t.page===1?'disabled':''}>Назад</button><button class="btn sm" data-action="page" data-page="${t.page+1}" ${t.page>=t.pages?'disabled':''}>Далее</button></div></div></section>`}
async function detailPage(id,token){let t;if(token)t=await api('/track',{headers:{'X-Tracking-Token':token}});else{[t,state.staff]=await Promise.all([api('/tickets/'+id),api('/users')])}state.ticket=t;state.trackingToken=token||null;const staff=!token;const events={created:'Заявка зарегистрирована',assignment:'Назначение исполнителя',comment:'Комментарий',details:'Уточнение параметров'};
 return `${title(esc(t.public_number),`Создана ${date(t.created_at)}`,`${btn(icon('refresh')+'Обновить','refresh','')}${token?btn(icon('copy')+'Ссылка','copy-tracking','',`data-token="${esc(token)}"`):''}`)}<div class="detail-grid"><div class="stack"><section class="card"><div class="actions" style="margin-bottom:18px">${statusBadge(t.status)}${priorityBadge(t.priority)}</div><h2 style="font-size:23px;line-height:1.4">${esc(t.title)}</h2><p class="detail-description">${esc(t.description)}</p><div class="detail-meta"><div><small>Категория</small><strong>${esc(t.category_name)}</strong></div><div><small>Помещение</small><strong>${esc(t.building)} · ${esc(t.room)}</strong></div><div><small>${staff?'Исполнитель':'Последнее обновление'}</small><strong>${staff?esc(t.assignee_name||'Не назначен'):date(t.updated_at)}</strong></div></div><div id="attachments" data-attachments="${esc(JSON.stringify(t.attachments))}"></div>${staff&&t.requester_name?`<p class="muted small" style="margin:22px 0 0">Заявитель: ${esc(t.requester_name)}</p>`:''}</section><section class="card"><div class="card-head"><h2>Обсуждение</h2><span class="muted small">${t.comments.length} комментариев</span></div>${t.comments.length?t.comments.map(c=>`<article class="comment ${c.visibility==='internal'?'internal':''}"><div class="comment-head"><strong>${esc(c.author_name)} ${c.visibility==='internal'?'· Внутренняя заметка':''}</strong><time>${date(c.created_at)}</time></div><p>${esc(c.body)}</p></article>`).join(''):'<p class="muted small">Здесь появятся комментарии сотрудника. Можно добавить подробности о проблеме.</p>'}<form id="comment-form">${errorSlot}${field('Ваш комментарий',`<textarea name="body" required maxlength="3000" placeholder="Уточните детали или задайте вопрос…" style="min-height:90px"></textarea>`)}<div class="actions">${staff?select('visibility',[{id:'public',name:'Виден заявителю'},{id:'internal',name:'Внутренняя заметка'}],'public',null,'style="width:auto" aria-label="Видимость комментария"'):''}<button type="submit" class="btn primary">${icon('send')}Отправить</button></div></form></section>${token&&t.status==='resolved'?`<section class="card text-center"><h2>Как всё прошло?</h2><p class="muted small">Оцените результат решения вашего обращения.</p><form id="rating-form">${errorSlot}<div class="rating">${[1,2,3,4,5].map(v=>`<label class="${v<=(t.rating||0)?'selected':''}"><input type="radio" name="rating" value="${v}" ${t.rating===v?'checked':''} required aria-label="${v} из 5">${icon('star')}</label>`).join('')}</div>${field('Комментарий к оценке <span class="optional">необязательно</span>',input('comment','Что можно улучшить?',t.rating_comment||'','maxlength="1000"'))}<button class="btn soft">${t.rating?'Обновить оценку':'Отправить оценку'}</button></form></section>`:''}</div><aside class="stack">${staff?`<section class="card"><h3>Управление заявкой</h3><form id="update-ticket-form">${errorSlot}${field('Статус',select('status',[t.status,...t.allowed_statuses].map(id=>({id,name:state.meta.statuses[id]})),t.status,null))}${field('Исполнитель',select('assignee_id',state.staff.filter(x=>x.active).map(x=>({id:x.id,name:x.name})),t.assignee_id,'Не назначен'))}${field('Приоритет',select('priority',Object.entries(state.meta.priorities).map(([id,name])=>({id,name})),t.priority,null))}${field('Категория',select('category_id',state.meta.categories,t.category_id,null))}${field('Результат или пояснение',`<textarea name="note" placeholder="Обязательно при решении или отклонении" maxlength="3000" style="min-height:90px"></textarea>`,'Этот комментарий будет виден заявителю.')}<button class="btn primary w-full">Сохранить изменения</button></form></section>`:`<div class="hint ${t.status==='needs_info'?'warning':''}" style="margin-top:0">${icon('info')}${t.status==='needs_info'?'Сотрудник запросил уточнение. Посмотрите комментарии и добавьте ответ.':'Статус меняет сотрудник УПК. Нажмите «Обновить», чтобы проверить изменения.'}</div>`}<section class="card"><h3>История обращения</h3><div class="timeline">${t.history.slice().reverse().map(h=>`<div class="timeline-item"><strong>${h.event==='status'?esc(state.meta.statuses[h.new_status]):esc(events[h.event]||h.event)}</strong><small>${date(h.created_at)}<br>${esc(h.actor_name)}</small>${h.note?`<p>${esc(h.note)}</p>`:''}</div>`).join('')}</div></section>${staff&&t.rating?`<div class="card"><h3>Оценка заявителя</h3><p class="blue">${t.rating} / 5 ${icon('star')}</p><p class="muted small">${esc(t.rating_comment)}</p></div>`:''}</aside></div>`}
async function analyticsPage(){const s=await api('/stats');const answers=s.ai.filter(x=>x.kind==='question').reduce((a,b)=>a+b.count,0),handoff=s.ai.filter(x=>x.kind!=='question').reduce((a,b)=>a+b.count,0);return `${title('Аналитика','Реальные показатели из журнала обращений.','<a class="btn" href="/api/export.csv">'+icon('download')+'Скачать отчёт</a>')}${statCards(s.totals)}<div class="grid-2"><section class="card"><div class="card-head"><h2>Категории обращений</h2><span class="notice-count">За всё время</span></div>${categoryBars(s.categories)}</section><section class="card"><div class="card-head"><h2>Обращения по помещениям</h2></div>${categoryBars(s.locations.map(l=>({name:l.room+' · '+l.zone_name,count:l.total})))}<p class="muted small">Открытые проблемы также отображаются на схеме помещений.</p></section><section class="card"><div class="card-head"><h2>Повторяющиеся проблемы</h2></div>${s.repeats.length?s.repeats.map(r=>`<div class="article-row">${box('refresh')}<div><h3>${esc(r.category)} · ${esc(r.room)}</h3><p>Обращений в этой категории и помещении: ${r.count}</p></div></div>`).join(''):'<p class="muted small">Повторных сочетаний категории и помещения пока нет.</p>'}<div class="hint">Повторяемость — сигнал для проверки, а не доказательство одной и той же неисправности.</div></section><section class="card"><div class="card-head"><h2>Работа помощника</h2><span class="demo-badge">Демонстрация</span></div><div class="grid-2"><div><p class="muted small">Ответы по инструкции</p><h1>${answers}</h1></div><div><p class="muted small">Рекомендовано передать человеку</p><h1>${handoff}</h1></div></div><div class="hint">Считаются обращения к помощнику. Рекомендация создать заявку не означает, что пользователь её отправил.</div><div class="article-row">${box('star')}<div><h3>Оценка решения: ${s.totals.rating??'нет оценок'}${s.totals.rating?' / 5':''}</h3><p>На основе оценок заявителей по решённым заявкам.</p></div></div></section></div>`}
async function locationsPage(){let stats=null;if(state.user)stats=await api('/stats');const rooms=state.meta.locations;const current=routeInfo().params.get('floor')||'all';const floors=[...new Set(rooms.map(l=>l.floor))].sort((a,b)=>a-b);const visible=rooms.filter(l=>current==='all'||String(l.floor)===current);return `${title('Помещения и QR-коды','Быстрый путь от двери аудитории к форме обращения.',`${btn(icon('printer')+'Печать QR','print','')}${state.user?.role==='admin'?btn(icon('plus')+'Помещение','edit-location','primary'):''}`)}<div class="hint no-print">${icon('info')}Демонстрационные помещения: схема условная, не архитектурный план колледжа. QR ведут на <strong>${esc(state.meta.public_base_url||location.origin)}</strong>. Для смартфона укажите сетевой адрес компьютера в <code>PUBLIC_BASE_URL</code>.</div><section class="card no-print"><div class="card-head"><h2>Схема помещений</h2><select id="floor-filter" style="width:auto" aria-label="Выбор этажа"><option value="all">Все этажи</option>${floors.map(f=>`<option value="${f}" ${String(f)===current?'selected':''}>${f} этаж</option>`).join('')}</select></div><div class="map">${visible.map(l=>{const count=stats?.locations.find(x=>x.id===l.id)?.open||0;return `<a href="${state.user?'#/tickets?location_id='+l.id:'#/new?location='+l.qr_key}" class="map-room ${count?'has-issues':''}">${count?`<span class="map-count">${count} открыто</span>`:''}<strong>${esc(l.room)}</strong><small>${esc(l.zone_name)} · ${l.floor} этаж</small></a>`}).join('')}</div><p class="muted small" style="margin:15px 0 0">${state.user?'Нажмите на помещение, чтобы посмотреть его заявки.':'Нажмите на помещение, чтобы сообщить о проблеме.'}</p></section><div class="section-head"><h2>QR-коды помещений</h2><span class="muted small">${visible.length} локаций</span></div><div class="grid-2">${visible.map(l=>`<section class="card qr-card"><img src="/api/qr/${encodeURIComponent(l.qr_key)}.png" alt="QR-код: ${esc(l.room)}"><div><h3>${esc(l.room)} · ${esc(l.zone_name)}</h3><p>${esc(l.building)} · ${l.floor} этаж<br>Отсканируйте, чтобы сообщить о проблеме</p><div class="actions no-print"><a class="btn sm" href="/api/qr/${encodeURIComponent(l.qr_key)}.png?download=1">${icon('download')}PNG</a><a class="btn sm" href="#/new?location=${encodeURIComponent(l.qr_key)}">Открыть</a>${state.user?.role==='admin'?btn('Изменить','edit-location','ghost',`data-id="${l.id}"`):''}</div><p class="print-only small">${esc(state.meta.public_base_url||location.origin)}</p></div></section>`).join('')}</div>`}
async function notificationsPage(){const items=await api('/notifications');const labels={demo:'Деморежим',pending:'В очереди',sending:'Отправляется',sent:'Отправлено',failed:'Не подтверждено'};return `${title('Журнал уведомлений','Обновления по обращениям: email и Telegram.',btn(icon('refresh')+'Обновить','refresh',''))}<div class="hint">${state.meta.notification_mode==='demo'?'Работает демонстрационный режим: сообщения сохраняются здесь, но не отправляются. Для реальной доставки настройте сервер и запустите обработчик очереди по README.':'Доставка выполняется отдельным обработчиком очереди. Статус «Отправлено» появляется только после подтверждения провайдера.'}</div><div class="card">${items.length?items.map(n=>`<div class="article-row">${box(n.channel==='email'?'mail':'send')}<div style="flex:1"><h3>${esc(n.public_number)} · ${n.channel==='email'?'Email':'Telegram'}</h3><p>${esc(n.body)}</p>${n.error?`<p style="color:#b24c55">${esc(n.error)}</p>`:''}<p style="margin-top:6px;font-size:10px">${date(n.created_at)}</p></div><span class="badge ${n.status==='sent'?'resolved':n.status==='failed'?'rejected':''}">${labels[n.status]||esc(n.status)}</span></div>`).join(''):empty('Уведомлений пока нет','При создании заявки укажите email или Telegram chat ID и согласие на уведомления. Обновления появятся здесь.')}</div>`}
async function settingsPage(){const [users,settings]=await Promise.all([api('/users'),api('/settings')]);state.staff=users;state.settings=settings;return `${title('Настройки','Пользователи, категории и автоматическое назначение.')}<div class="grid-2"><section class="card settings-section"><div class="card-head"><h2>Сотрудники</h2>${btn(icon('plus')+'Добавить','add-user','soft')}</div>${users.map(u=>`<div class="user-row"><span class="avatar">${esc(u.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</span><div class="content"><strong>${esc(u.name)}</strong><small>${esc(u.login)} · ${u.role==='admin'?'Администратор':'Сотрудник'} · ${u.active?'Активен':'Отключён'}</small></div><div class="actions">${u.id!==state.user.id?`${btn(u.active?'Отключить':'Включить','toggle-user','ghost',`data-id="${u.id}" data-active="${u.active?0:1}"`)}${btn('Роль','user-role','ghost',`data-id="${u.id}"`)}`:''}${btn('Пароль','user-password','ghost',`data-id="${u.id}"`)}</div></div>`).join('')}</section><section class="card settings-section"><div class="card-head"><h2>Категории и маршрутизация</h2>${btn(icon('plus'),'edit-category','soft','aria-label="Добавить категорию"')}</div><p class="muted small">Новая заявка автоматически получит исполнителя своей категории. Статус останется «Новая» до рассмотрения.</p>${settings.categories.map(c=>`<div class="article-row">${box(c.icon)}<div style="flex:1"><h3>${esc(c.name)}</h3><p>${esc(users.find(u=>u.id===c.assignee_id)?.name||'Исполнитель не назначен')}</p></div>${btn('Изменить','edit-category','ghost',`data-id="${esc(c.id)}"`)}</div>`).join('')}</section></div><section class="card"><div class="card-head"><h2>Журнал административных действий</h2></div>${settings.audit.length?settings.audit.map(a=>`<div class="article-row"><div><h3>${esc(a.action)}</h3><p>${esc(a.name)} · ${date(a.created_at)}</p></div></div>`).join(''):'<p class="muted small">Пока нет изменений. Управление пользователями, категориями и помещениями записывается здесь.</p>'}</section>`}
let photoUrls=[];
async function render(){const version=++state.routeVersion;photoUrls.forEach(URL.revokeObjectURL);photoUrls=[];const {path}=routeInfo();shell('<div class="loading"><div class="spin"></div>Загружаем…</div>');
 try{
  let content;const staffRoutes=['/dashboard','/tickets','/analytics','/notifications','/settings'];
  if((staffRoutes.includes(path)||path.startsWith('/ticket/'))&&!state.user){content=loginPage()}
  else if(path==='/settings'&&state.user.role!=='admin'){content=empty('Недостаточно прав','Этот раздел доступен только администратору.')}
  else if(path==='/')content=home();else if(path==='/new')content=newTicket();else if(path==='/created')content=createdPage();else if(path==='/mine')content=minePage();else if(path==='/login')content=state.user?empty('Вы уже вошли',state.user.name,'<a class="btn primary" href="#/dashboard">В панель УПК</a>'):loginPage();else if(path==='/assistant')content=chatPage();else if(path.startsWith('/knowledge'))content=knowledgePage(path.split('/')[2]);else if(path==='/dashboard')content=await dashboardPage();else if(path==='/tickets')content=await ticketsPage();else if(path.startsWith('/ticket/'))content=await detailPage(path.split('/')[2]);else if(path.startsWith('/track/'))content=await detailPage(null,path.split('/')[2]);else if(path==='/analytics')content=await analyticsPage();else if(path==='/locations')content=await locationsPage();else if(path==='/notifications')content=await notificationsPage();else if(path==='/settings')content=await settingsPage();else content=empty('Страница не найдена','Вернитесь на главную страницу.','<a class="btn primary" href="#/">На главную</a>');
  if(version!==state.routeVersion)return;shell(content);document.title=($('#main h1')?.textContent||'УПК')+' — УПК, колледж ДГУ';
  if(path==='/new'&&state.photo)showPhoto();
  const attachments=$('#attachments');if(attachments){for(const a of state.ticket.attachments){const r=await fetch('/api/attachments/'+a.id,{headers:state.trackingToken?{'X-Tracking-Token':state.trackingToken}:{}});if(version!==state.routeVersion)return;if(r.ok){const url=URL.createObjectURL(await r.blob());photoUrls.push(url);attachments.insertAdjacentHTML('beforeend',`<img src="${url}" class="attachment-img" alt="Фотография проблемы, приложенная заявителем">`)}else attachments.insertAdjacentHTML('beforeend','<p class="muted small">Фотографию не удалось загрузить.</p>')}}
  if(path==='/assistant'){const chat=$('#chat-messages');chat.scrollTop=chat.scrollHeight}
 }catch(e){if(version!==state.routeVersion)return;if(e.status===401){state.user=null;shell(loginPage());toast('Сессия истекла. Войдите снова.')}else shell(empty('Не удалось открыть страницу',esc(e.message),btn('Повторить','refresh','primary')))}
}
function formData(form){return Object.fromEntries(new FormData(form).entries())}
function showPhoto(){const preview=$('#photo-preview');if(!preview)return;preview.innerHTML=state.photo?`<div class="photo-preview"><img src="${state.photo}" alt="Предпросмотр выбранного фото"><div><p class="small muted" style="margin-bottom:9px">Фотография будет доступна только по ссылке заявки и сотрудникам.</p><div class="actions">${btn(icon('sparkles')+'Анализ фото','analyze-photo','soft','type="button"')}${btn('Убрать','remove-photo','ghost','type="button"')}</div></div></div><div id="photo-analysis-result"></div>`:''}
async function similarCheck(){const f=$('#new-ticket-form');if(!f)return;const d=formData(f);if(!d.category_id||!d.location_id)return;try{const r=await api('/similar',{method:'POST',body:d});const target=$('#similar-result');if(target)target.innerHTML=r.count?`<div class="hint warning">${icon('info')}${esc(r.message)}</div>`:''}catch(e){toast(e.message)}}
function modal(heading,body){const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2>${heading}</h2><button class="close" data-action="close-modal" aria-label="Закрыть">${icon('close')}</button></div><div class="modal-body">${body}</div>`;d.showModal()}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Ссылка скопирована')}catch{modal('Сохраните ссылку',`<p class="muted small">Автоматическое копирование недоступно. Выделите и скопируйте ссылку.</p><textarea readonly>${esc(text)}</textarea>`);$('#modal textarea').select()}}
async function ask(text){state.chat.push({role:'user',text});const r=await api('/assistant',{method:'POST',body:{text}});state.chat.push({role:'assistant',result:r});await render();$('#chat-input')?.focus()}
function rememberDraft(){const form=$('#new-ticket-form');if(form)state.draft={...state.draft,...formData(form)}}

// One delegated handler keeps actions working after route changes without inline scripts.
document.addEventListener('click',async event=>{
 const actionEl=event.target.closest('[data-action]');if(!actionEl)return;const action=actionEl.dataset.action;
 if(action==='menu'){$('.sidebar')?.classList.toggle('open');$('.mobile-scrim')?.classList.toggle('open');return}
 if(action==='close-modal'){$('#modal').close();return}
 const originallyDisabled=actionEl.disabled;actionEl.disabled=true;
 try{
  if(action==='logout'){await api('/logout',{method:'POST',body:{}});state.user=null;state.meta.user=null;go('/');toast('Вы вышли из учётной записи')}
  else if(action==='refresh')await render();
  else if(action==='copy-tracking')await copy(location.origin+location.pathname+'#/track/'+actionEl.dataset.token);
  else if(action==='forget'){const token=actionEl.dataset.token;modal('Убрать сохранённую ссылку?',`<p class="muted">Заявка останется в системе, но ссылка исчезнет с этого устройства. Сначала сохраните её в другом месте.</p><div class="actions">${btn('Убрать с устройства','confirm-forget','danger',`data-token="${esc(token)}"`)}${btn('Отмена','close-modal','')}</div>`)}
  else if(action==='confirm-forget'){localStorage.setItem('upk-own-tickets',JSON.stringify(saved().filter(x=>x.token!==actionEl.dataset.token)));$('#modal').close();await render();toast('Ссылка убрана с устройства')}
  else if(action==='analyze-draft'){rememberDraft();const text=state.draft.description;if(!text||text.trim().length<2)throw Error('Сначала опишите проблему.');const r=await api('/assistant',{method:'POST',body:{text}});const target=$('#draft-analysis');if(target){target.innerHTML=assistantResult(r,false);const f=$('#new-ticket-form');if(state.meta.categories.some(c=>c.id===r.category))f.elements.category_id.value=r.category;if(!f.elements.title.value)f.elements.title.value=r.title;rememberDraft();await similarCheck()}}
  else if(action==='remove-photo'){state.photo=null;$('#photo-input').value='';showPhoto()}
  else if(action==='analyze-photo'){if(!state.photo)throw Error('Сначала выберите фото.');if(state.meta.photo_mode==='connected'){modal('Распознать фотографию?',`<p>Для анализа фотография будет отправлена внешнему сервису, настроенному администратором. Не отправляйте фото с личными данными.</p><div class="actions">${btn('Отправить на анализ','confirm-photo','primary')}${btn('Отмена','close-modal','')}</div>`)}else await runPhotoAnalysis()}
  else if(action==='confirm-photo'){$('#modal').close();await runPhotoAnalysis()}
  else if(action==='apply-photo'){const desc=$('#new-ticket-form textarea[name=description]');desc.value=(desc.value?desc.value+'\n':'')+(state.photoDescription||'');rememberDraft();toast('Описание добавлено. Проверьте его перед отправкой.')}
  else if(action==='ask-example'){const text=actionEl.dataset.text;$('#chat-input').value=text;$('#chat-form').requestSubmit()}
  else if(action==='chat-to-ticket'){const index=Number(actionEl.closest('[data-chat-index]')?.dataset.chatIndex);const source=Number.isInteger(index)&&state.chat[index-1]?.role==='user'?state.chat[index-1]:[...state.chat].reverse().find(x=>x.role==='user');const result=Number.isInteger(index)&&state.chat[index]?.result?state.chat[index].result:[...state.chat].reverse().find(x=>x.result)?.result;state.draft={description:source?.text||'',title:result?.title||'',category_id:result?.category||''};state.requestKey=null;go('/new')}
  else if(action==='reset-filters')go('/tickets');
  else if(action==='ticket-tab'){const p=routeInfo().params;p.delete('page');if(actionEl.dataset.status)p.set('status',actionEl.dataset.status);else p.delete('status');go('/tickets?'+p.toString())}
  else if(action==='page'){const p=routeInfo().params;p.set('page',actionEl.dataset.page);go('/tickets?'+p.toString())}
  else if(action==='print')window.print();
  else if(action==='edit-location'){const l=state.meta.locations.find(x=>String(x.id)===actionEl.dataset.id)||{};modal(l.id?'Изменить помещение':'Новое помещение',`<form id="location-form">${errorSlot}<input type="hidden" name="id" value="${l.id||''}">${field('Корпус',input('building','Главный корпус',l.building||'Главный корпус','required maxlength="100"'))}<div class="field-row">${field('Этаж',input('floor','2',l.floor??2,'type="number" required min="-3" max="50"'))}${field('Кабинет или зона',input('room','214',l.room||'','required maxlength="60"'))}</div>${field('Назначение',input('zone_name','Учебная аудитория',l.zone_name||'','required maxlength="100"'))}${field('QR-ключ',input('qr_key','room-214',l.qr_key||'','required pattern="[a-zA-Z0-9_\\-]{3,80}"'),'Изменение ключа делает прежний QR-код недействительным. Для новой привязки старого кода сохраните ключ и измените помещение.')}<button class="btn primary w-full">Сохранить</button></form>`)}
  else if(action==='add-user')modal('Добавить сотрудника',`<form id="user-form">${errorSlot}${field('Имя и фамилия',input('name','Имя Фамилия','','required minlength="2" maxlength="100"'))}${field('Логин',input('login','employee','','required minlength="3" maxlength="50" pattern="[a-zA-Z0-9_.\\-]+" autocomplete="off"'))}${field('Пароль',input('password','Не менее 12 символов','','type="password" required minlength="12" maxlength="200" autocomplete="new-password"'))}${field('Роль',select('role',[{id:'staff',name:'Сотрудник УПК'},{id:'admin',name:'Администратор'}],'staff',null))}<button class="btn primary w-full">Создать учётную запись</button></form>`);
  else if(action==='toggle-user'){const u=state.staff.find(x=>String(x.id)===actionEl.dataset.id);modal(u.active?'Отключить сотрудника?':'Включить сотрудника?',`<p>${esc(u.name)} · ${esc(u.login)}</p><p class="muted small">${u.active?'Текущие сессии будут завершены. Автоматическое назначение этому сотруднику отключится. Существующие заявки останутся в журнале.':'Сотрудник снова сможет войти в свою учётную запись.'}</p>${btn('Подтвердить','confirm-user-active','primary',`data-id="${u.id}" data-active="${u.active?0:1}"`)}`)}
  else if(action==='confirm-user-active'){await api('/users/'+actionEl.dataset.id,{method:'PATCH',body:{active:actionEl.dataset.active==='1'}});$('#modal').close();await render();toast('Учётная запись обновлена')}
  else if(action==='user-role'){const u=state.staff.find(x=>String(x.id)===actionEl.dataset.id);modal('Роль сотрудника',`<form id="role-form" data-id="${u.id}">${errorSlot}<p>${esc(u.name)}</p>${field('Роль',select('role',[{id:'staff',name:'Сотрудник УПК'},{id:'admin',name:'Администратор'}],u.role,null))}<button class="btn primary">Сохранить</button></form>`)}
  else if(action==='user-password')modal('Новый пароль',`<form id="password-form" data-id="${actionEl.dataset.id}">${errorSlot}${field('Пароль',input('password','Не менее 12 символов','','required minlength="12" maxlength="200" type="password" autocomplete="new-password"'))}<p class="muted small">Все текущие сессии этого сотрудника будут завершены.</p><button class="btn primary">Установить пароль</button></form>`);
  else if(action==='edit-category'){const c=state.settings.categories.find(x=>x.id===actionEl.dataset.id)||{};modal(c.id?'Категория и назначение':'Новая категория',`<form id="category-form">${errorSlot}${field('Ключ',input('id','equipment',c.id||'','required pattern="[a-z0-9_\\-]{2,60}" '+(c.id?'readonly':'')))}${field('Название',input('name','Оборудование',c.name||'','required minlength="2" maxlength="80"'))}${field('Исполнитель новых заявок',select('assignee_id',state.staff.filter(x=>x.active).map(u=>({id:u.id,name:u.name})),c.assignee_id,'Не назначать автоматически'))}<button class="btn primary">Сохранить</button></form>`)}
 }catch(e){toast(e.message)}finally{if(actionEl.isConnected)actionEl.disabled=originallyDisabled}
});
async function runPhotoAnalysis(){const r=await api('/photo-analysis',{method:'POST',body:{photo:state.photo}});state.photoDescription=r.description;const target=$('#photo-analysis-result');if(target)target.innerHTML=`<div class="hint">${esc(r.message)}${r.description?`<p style="margin-top:10px">${esc(r.description)}</p>${btn('Добавить к описанию','apply-photo','soft','type="button"')}`:''}</div>`}
let submittingChat=false;
document.addEventListener('submit',async event=>{
 const form=event.target;if(!form.getAttribute('id'))return;event.preventDefault();const data=formData(form);const error=$('.form-error',form);if(error)error.textContent='';const button=$('button[type=submit]',form)||$('button:not([type=button])',form);if(form.dataset.busy)return;form.dataset.busy='1';if(button)button.disabled=true;
 try{
  if(form.getAttribute('id')==='login-form'){const r=await api('/login',{method:'POST',body:data});state.user=r.user;await reloadMeta();go('/dashboard')}
  else if(form.getAttribute('id')==='new-ticket-form'){
   rememberDraft();const r=await api('/tickets',{method:'POST',body:{...data,request_key:state.requestKey,photo:state.photo,notification_consent:form.elements.notification_consent.checked}});
   state.lastCreated=r;saveOwn({...r,title:data.title,created_at:new Date().toISOString()});state.draft={};state.photo=null;state.requestKey=null;go('/created');
  }else if(form.getAttribute('id')==='track-form'){
   let token=data.token.trim();if(token.includes('#/track/'))token=token.split('#/track/')[1].split(/[?\s]/)[0];if(!/^[A-Za-z0-9_-]{43}$/.test(token))throw Error('Введите полный код доступа или секретную ссылку из подтверждения.');go('/track/'+token)
  }else if(form.getAttribute('id')==='chat-form'){
   if(submittingChat)return;submittingChat=true;try{await ask(data.text)}finally{submittingChat=false}
  }else if(form.getAttribute('id')==='filters-form'){const p=new URLSearchParams();Object.entries(data).forEach(([k,v])=>{if(v)p.set(k,v)});go('/tickets?'+p.toString())}
  else if(form.getAttribute('id')==='comment-form'){await api('/tickets/'+state.ticket.id+'/comments',{method:'POST',body:data,headers:state.trackingToken?{'X-Tracking-Token':state.trackingToken}:{}});await render();toast('Комментарий добавлен')}
  else if(form.getAttribute('id')==='rating-form'){await api('/tickets/'+state.ticket.id+'/rating',{method:'POST',body:data,headers:{'X-Tracking-Token':state.trackingToken}});await render();toast('Спасибо за вашу оценку!')}
  else if(form.getAttribute('id')==='update-ticket-form'){await api('/tickets/'+state.ticket.id,{method:'PATCH',body:{...data,version:state.ticket.version}});await render();toast('Изменения сохранены')}
  else if(form.getAttribute('id')==='location-form'){await api('/locations',{method:'POST',body:data});$('#modal').close();await reloadMeta();await render();toast('Помещение сохранено')}
  else if(form.getAttribute('id')==='user-form'){await api('/users',{method:'POST',body:data});$('#modal').close();await render();toast('Учётная запись создана')}
  else if(form.getAttribute('id')==='category-form'){await api('/categories',{method:'POST',body:data});$('#modal').close();await reloadMeta();await render();toast('Категория сохранена')}
  else if(form.getAttribute('id')==='role-form'||form.getAttribute('id')==='password-form'){await api('/users/'+form.dataset.id,{method:'PATCH',body:data});$('#modal').close();if(form.getAttribute('id')==='password-form'&&String(state.user.id)===form.dataset.id){await reloadMeta();go('/login')}else await render();toast('Учётная запись обновлена')}
 }catch(e){if(error&&error.isConnected){error.textContent=e.message;error.scrollIntoView({behavior:'smooth',block:'nearest'})}else toast(e.message)}finally{delete form.dataset.busy;if(button?.isConnected)button.disabled=false}
});
document.addEventListener('change',async event=>{
 const el=event.target;
 if(el.id==='photo-input'){
  const file=el.files[0];if(!file)return;
  if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5*1024*1024){el.value='';toast('Выберите JPEG, PNG или WebP размером до 5 МБ.');return}
  const reader=new FileReader();reader.onload=()=>{state.photo=reader.result;showPhoto()};reader.onerror=()=>toast('Не удалось прочитать файл.');reader.readAsDataURL(file)
 }else if(el.closest('#new-ticket-form')){rememberDraft();if(['location_id','category_id'].includes(el.name))await similarCheck()}
 else if(el.id==='floor-filter')go('/locations?floor='+el.value);
 else if(el.name==='rating')$$('.rating label').forEach((l,i)=>l.classList.toggle('selected',i<Number(el.value)));
});
document.addEventListener('input',event=>{if(event.target.id==='kb-search'){const q=event.target.value.toLowerCase();$('#knowledge-results').innerHTML=knowledgeCards(state.meta.knowledge.filter(a=>(a.title+' '+a.summary+' '+a.steps.join(' ')).toLowerCase().includes(q)))}if(event.target.closest('#new-ticket-form'))rememberDraft()});
window.addEventListener('hashchange',()=>{window.scrollTo(0,0);render()});
async function start(){try{await reloadMeta();await render()}catch(e){$('#app').innerHTML=`<main class="main"><div class="card">${empty('Не удалось подключиться',esc(e.message),'<button class="btn primary" id="retry-start">Повторить</button>')}</div></main>`;$('#retry-start').onclick=start}}
start();
